import{c as t,Q as a,j as r,m as o}from"./chunks/framework.DOi4mjdC.js";const p=JSON.parse('{"title":"SIMT语言扩展层C API","description":"","frontmatter":{},"headers":[{"level":1,"title":"SIMT语言扩展层C API","slug":"simt语言扩展层c-api"}],"relativePath":"guide/编程指南/语言扩展层/SIMT语言扩展层C-API.md","filePath":"guide/编程指南/语言扩展层/SIMT语言扩展层C-API.md"}'),c={name:"guide/编程指南/语言扩展层/SIMT语言扩展层C-API.md"};function i(n,e,l,s,d,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="simt语言扩展层c-api" tabindex="-1">SIMT语言扩展层C API <a class="header-anchor" href="#simt语言扩展层c-api" aria-label="Permalink to &quot;SIMT语言扩展层C API&quot;">​</a></h1><p>SIMT编程基于AI Core的硬件能力实现，可以使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/asc_vf_call.md" target="_blank" rel="noreferrer">asc_vf_call</a>接口启动SIMT VF（Vector Function）子任务。当前，SIMT语言扩展层支持的C API类别如下：</p><ul><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%90%8C%E6%AD%A5%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">同步函数</a>：提供内存管理与同步接口，解决不同核内的线程间可能存在的数据竞争以及线程的同步问题。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E6%95%B0%E5%AD%A6%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">数学函数</a>：提供处理数学运算的函数接口集合。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E7%B2%BE%E5%BA%A6%E8%BD%AC%E6%8D%A2.md" target="_blank" rel="noreferrer">精度转换</a>：提供不同精度类型间的转换功能的一系列API接口。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E6%AF%94%E8%BE%83%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">比较函数</a>：用于判断数据是否为有限数、无穷或nan。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Atmoic%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">Atomic函数</a>：提供对Unified Buffer或Global Memory上的数据与指定数据执行原子操作的一系列API接口。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Warp%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">Warp函数</a>：提供对单个Warp内32个线程的数据进行处理的相关操作的一系列API接口。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2-141.md" target="_blank" rel="noreferrer">类型转换</a>：根据源操作数和目的操作数的数据类型进行精度转换。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%90%91%E9%87%8F%E7%B1%BB%E5%9E%8B%E6%9E%84%E9%80%A0%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">向量类型构造函数</a>：向量类型构造相关接口。</li><li>专用函数：专用函数相关接口，包含<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E4%BD%BF%E8%83%BDCache-Hints%E7%9A%84Load-Store%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">使能Cache Hints的Load/Store函数</a>相关接口。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/printf-147.md" target="_blank" rel="noreferrer">调测接口</a>：SIMT VF调试场景下使用的相关接口。</li></ul>',3)])])}const _=t(c,[["render",i]]);export{p as __pageData,_ as default};
